begin;
-- These baseline assertions are transaction-local, even after Education is enabled.
update public.app_settings set generation_paused=true,claims_paused=true where id='global';
-- This suite exercises all input modes and offline admission, not runtime availability.
update public.app_settings set limits=limits||'{"enabledGenerationModes":["education","software","branding"]}' where id='global';
update public.workers set enabled=false;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_function_privilege('anon','public.enqueue_generation(uuid,text,jsonb)','execute'),'Anonymous cannot enqueue');
select ok(has_function_privilege('authenticated','public.enqueue_generation(uuid,text,jsonb)','execute'),'Authenticated enqueue is granted');
select ok(not has_function_privilege('authenticated','private.complete_generation_input(jsonb,text)','execute'),'Private validator stays private');
select ok(not has_table_privilege('authenticated','public.jobs','INSERT'),'No direct job writes');
select ok(not has_table_privilege('authenticated','public.usage_reservations','INSERT'),'No direct reservations');
insert into auth.users(id,email,raw_user_meta_data) select ('b1400000-0000-4000-8000-00000000000'||n)::uuid,'w14-sql-'||n||'@example.invalid','{"display_name":"Queue fixture"}' from generate_series(1,4) n;
insert into public.usage_accounts(scope,owner_id,byte_limit,output_limit) select 'user',('b1400000-0000-4000-8000-00000000000'||n)::uuid,400000000,3 from generate_series(1,4) n;
update public.usage_accounts set byte_limit=1073741824 where scope='global';
update public.app_settings set generation_paused=true,limits=limits||'{"globalByteLimitConfigured":true}'::jsonb;
insert into public.projects(id,owner_id,title,mode,draft_input,preferences)
select ('b1400000-0000-4000-8000-00000000001'||n)::uuid,('b1400000-0000-4000-8000-00000000000'||n)::uuid,'Queue project','education','{"mode":"education","topic":"How turbines work","audience":"beginner","intendedUse":"personal-learning","sources":[]}','{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"}' from generate_series(1,4) n;
create temporary table fixture(request jsonb,result jsonb,upload jsonb);
insert into fixture(request) values('{"draftVersion":1,"preferences":{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"},"acknowledgments":{"sourceRights":true,"externalAiProcessing":true,"policyVersion":"v1"}}');
select set_config('request.jwt.claims','{"sub":"b1400000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','paused',(select request from fixture))$$,'P1402',null::text,'Pause is enforced');
select is((select count(*)::integer from public.revisions where owner_id='b1400000-0000-4000-8000-000000000001'),0,'Rejected admission has no revision');
update public.app_settings set generation_paused=false;
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000012','foreign',(select request from fixture))$$,'42501',null::text,'Foreign project hidden');
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','stale',jsonb_set((select request from fixture),'{draftVersion}','2'))$$,'40001',null::text,'Stale draft rejected');
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','bad',jsonb_set((select request from fixture),'{acknowledgments,sourceRights}','false'))$$,'22023',null::text,'Consent cannot be forged false');
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','bad',(select request||'{"input":{}}'::jsonb from fixture))$$,'22023',null::text,'Arbitrary submitted content forbidden');
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','bad',jsonb_set((select request from fixture),'{preferences,voiceProfileId}','"other"'))$$,'22023',null::text,'Unavailable voice rejected');
update public.projects set draft_input=draft_input-'topic' where id='b1400000-0000-4000-8000-000000000011';
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','incomplete',jsonb_set((select request from fixture),'{draftVersion}','2'))$$,'22023',null::text,'Incomplete stored draft rejected');
update public.projects set draft_input=draft_input||'{"topic":"Original topic"}' where id='b1400000-0000-4000-8000-000000000011';
update fixture set request=jsonb_set(request,'{draftVersion}','3');
update public.usage_accounts set byte_limit=100 where owner_id='b1400000-0000-4000-8000-000000000001';
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','capacity',(select request from fixture))$$,'P1403',null::text,'User byte capacity enforced');
update public.usage_accounts set byte_limit=400000000,output_limit=0 where owner_id='b1400000-0000-4000-8000-000000000001';
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','outputs',(select request from fixture))$$,'P1404',null::text,'Configured output cap enforced');
update public.usage_accounts set output_limit=3 where owner_id='b1400000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','first','{"draftVersion":3,"preferences":{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"},"acknowledgments":{"sourceRights":true,"externalAiProcessing":true,"policyVersion":"v1"}}')$$,'Actual authenticated role can enqueue');
reset role;
update fixture set result=public.enqueue_generation('b1400000-0000-4000-8000-000000000011','first',request);
select is((select result->>'status' from fixture),'waiting_worker','Offline worker accepted as waiting');
select is((select result->>'reused' from fixture),'true','Receipt replay marked reused');
select is((select count(*)::integer from public.jobs where owner_id='b1400000-0000-4000-8000-000000000001'),1,'Exactly one job');
select is((select count(*)::integer from public.revisions where owner_id='b1400000-0000-4000-8000-000000000001'),1,'Exactly one frozen revision');
select is((select reserved_bytes from public.usage_accounts where owner_id='b1400000-0000-4000-8000-000000000001'),167772160::bigint,'One conservative byte reservation');
select is((select reserved_outputs from public.usage_accounts where owner_id='b1400000-0000-4000-8000-000000000001'),1,'One output reserved');
select is((select draft_version from public.projects where id='b1400000-0000-4000-8000-000000000011'),3,'Queue does not alter draft version');
select is((select next_revision_number from public.projects where id='b1400000-0000-4000-8000-000000000011'),2,'Revision number advanced once');
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','another',(select request from fixture))$$,'P1401',null::text,'Different key cannot create second active job');
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','first',jsonb_set((select request from fixture),'{preferences,targetSeconds}','75'))$$,'23505',null::text,'Same key changed payload conflicts');
update public.projects set title='Edited title',draft_input=draft_input||'{"topic":"Edited topic"}' where id='b1400000-0000-4000-8000-000000000011';
update public.app_settings set generation_paused=true;
select lives_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000011','first',(select request from fixture))$$,'Lost-response recovery precedes freshness and pause');
select is((select input_snapshot->'input'->>'topic' from public.revisions where id=(select (result->>'revisionId')::uuid from fixture)),'Original topic','Frozen content unchanged');
select ok((select input_snapshot->'acknowledgments' ? 'acceptedAt' from public.revisions where id=(select (result->>'revisionId')::uuid from fixture)),'Server consent timestamp frozen');
select throws_ok($$update public.revisions set input_snapshot='{}' where id=(select (result->>'revisionId')::uuid from fixture)$$,'23514',null::text,'Request content immutable');
select is((public.get_generation_job((select (result->>'jobId')::uuid from fixture))->'progress'->>'activeMs'),'0','Safe status uses decimal elapsed time');
select ok(not (public.get_generation_job((select (result->>'jobId')::uuid from fixture)) ?|array['input','worker_id','lease_token','budget_snapshot','object_key']),'Safe status excludes internals');
select set_config('request.jwt.claims','{"sub":"b1400000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.get_generation_job((select (result->>'jobId')::uuid from fixture)),null::jsonb,'Other user cannot read job');
update public.app_settings set generation_paused=false;
update public.projects set mode='software',draft_input='{"mode":"software","softwareName":"Fixture app","brief":"A useful app","intendedUse":"promotional","sources":[]}' where id='b1400000-0000-4000-8000-000000000012';
update fixture set upload=public.reserve_source_upload('b1400000-0000-4000-8000-000000000012',2,'image',repeat('b',64),'image.png','image/png',68,'image');
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000012','incomplete-upload',(select request from fixture))$$,'P1405',null::text,'Allocated source is not a received upload');
insert into storage.objects(bucket_id,name,metadata) select bucket,object_key,'{"size":68,"mimetype":"image/png"}'::jsonb from public.assets where id=(select (upload->'snapshot'->'items'->0->>'assetId')::uuid from fixture);
select lives_ok($$select public.change_source_upload((select (upload->>'uploadId')::uuid from fixture),'complete')$$,'Source receipt recorded (SQL metadata fixture, not decoded media)');
update public.assets set expires_at=now()-interval '1 second' where id=(select (upload->'snapshot'->'items'->0->>'assetId')::uuid from fixture);
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000012','expired',(select request from fixture))$$,'P1407',null::text,'Expired source cannot be frozen');
update public.assets set expires_at=now()+interval '1 day' where id=(select (upload->'snapshot'->'items'->0->>'assetId')::uuid from fixture);
update storage.objects set metadata='{"size":67,"mimetype":"image/png"}' where name=(select object_key from public.assets where id=(select (upload->'snapshot'->'items'->0->>'assetId')::uuid from fixture));
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000012','missing-receipt',(select request from fixture))$$,'P1405',null::text,'Receipt size mismatch is not trusted');
update storage.objects set metadata='{"size":68,"mimetype":"image/png"}' where name=(select object_key from public.assets where id=(select (upload->'snapshot'->'items'->0->>'assetId')::uuid from fixture));
update fixture set result=public.enqueue_generation('b1400000-0000-4000-8000-000000000012','software',request);
select is((select count(*)::integer from public.revision_assets where revision_id=(select (result->>'revisionId')::uuid from fixture)),1,'Exact owned source frozen');
select ok((select retain_until>=now()+interval '7 days' from public.revision_assets where revision_id=(select (result->>'revisionId')::uuid from fixture)),'Bounded queue source retention recorded');
select throws_ok($$select public.change_source_upload((select (upload->>'uploadId')::uuid from fixture),'remove')$$,'23514',null::text,'Frozen source cannot be removed');
select is((select state from public.assets where id=(select (upload->'snapshot'->'items'->0->>'assetId')::uuid from fixture)),'received','Enqueue does not pretend decoding occurred');
select set_config('request.jwt.claims','{"sub":"b1400000-0000-4000-8000-000000000003","role":"authenticated"}',true);
update public.usage_accounts set retained_outputs=3 where owner_id='b1400000-0000-4000-8000-000000000003';update public.usage_accounts set retained_outputs=retained_outputs+3 where scope='global';
update fixture set result=public.enqueue_generation('b1400000-0000-4000-8000-000000000013','reconcile',jsonb_set(request,'{draftVersion}','1'));
select is((select retained_outputs from public.usage_accounts where owner_id='b1400000-0000-4000-8000-000000000003'),0,'Obsolete retained counters reconciled without byte release');
select is((select count(*)::integer from public.job_events where job_id=(select (result->>'jobId')::uuid from fixture)),1,'Initial durable event');
select set_config('request.jwt.claims','{"sub":"b1400000-0000-4000-8000-000000000004","role":"authenticated"}',true);
create function pg_temp.fail_queue() returns trigger language plpgsql as $$begin if new.owner_id='b1400000-0000-4000-8000-000000000004' then raise exception 'deliberate queue failure';end if;return new;end$$;
create trigger w14_test_failure before insert on public.jobs for each row execute function pg_temp.fail_queue();
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000014','rollback',jsonb_set((select request from fixture),'{draftVersion}','1'))$$,'P0001','deliberate queue failure','Failure after revision insertion rolls back');
select is((select count(*)::integer from public.revisions where owner_id='b1400000-0000-4000-8000-000000000004'),0,'Failed transaction leaves no revision');
select is((select count(*)::integer from public.idempotency_requests where owner_id='b1400000-0000-4000-8000-000000000004'),0,'Failed transaction leaves no receipt');
select is((select reserved_bytes from public.usage_accounts where owner_id='b1400000-0000-4000-8000-000000000004'),0::bigint,'Failed transaction leaves no capacity charge');

drop trigger w14_test_failure on public.jobs;
update public.usage_accounts set reserved_outputs=3 where owner_id='b1400000-0000-4000-8000-000000000004';
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000014','slots',jsonb_set((select request from fixture),'{draftVersion}','1'))$$,'P1404',null::text,'Three reserved output slots cannot be bypassed');
update public.usage_accounts set reserved_outputs=0 where owner_id='b1400000-0000-4000-8000-000000000004';
update public.usage_accounts set byte_limit=used_bytes+reserved_bytes where scope='global';
select throws_ok($$select public.enqueue_generation('b1400000-0000-4000-8000-000000000014','global-full',jsonb_set((select request from fixture),'{draftVersion}','1'))$$,'P1403',null::text,'Global byte cap enforced');
update public.usage_accounts set byte_limit=1073741824 where scope='global';
update public.app_settings set claims_paused=false;
insert into public.workers(label,enabled,protocol_version,capabilities,last_seen_at) values('W14 fixture',true,1,'{"modes":["education"]}',now());
update fixture set result=public.enqueue_generation('b1400000-0000-4000-8000-000000000014','online',jsonb_set(request,'{draftVersion}','1'));
select is((select result->>'status' from fixture),'queued','Healthy compatible worker admits queued status');
update public.profiles set status='disabled' where id='b1400000-0000-4000-8000-000000000004';
select throws_ok($$select public.get_generation_job((select (result->>'jobId')::uuid from fixture))$$,'42501',null::text,'Disabled account cannot read receipt');
select ok(private.complete_generation_input('{"mode":"education","title":"Video","topic":"Turbines","audience":"beginner","intendedUse":"personal-learning","sources":[]}','education'),'Complete Education accepted');
select ok(not private.complete_generation_input('{"mode":"education","title":"Video","topic":" ","audience":"beginner","intendedUse":"personal-learning","sources":[]}','education'),'Whitespace topic rejected');
select ok(not private.complete_generation_input('{"mode":"education","title":"Video","topic":"Turbines","audience":null,"intendedUse":"personal-learning","sources":[]}','education'),'Null audience rejected');
select ok(not private.complete_generation_input('{"mode":"education","title":"Video","topic":"Turbines","audience":"beginner","intendedUse":"personal-learning","sources":[],"url":"https://example.invalid"}','education'),'Unknown content field rejected');
select ok(not private.complete_generation_input(jsonb_build_object('mode','education','title','Video','topic','Turbines','audience','beginner','intendedUse','personal-learning','sources','[]'::jsonb,'brief',repeat('x',3999),'learningObjective','abc'),'education'),'Combined source budget enforced in SQL');
select ok(not private.complete_generation_input(jsonb_build_object('mode','education','title','Video','topic','Turbines','audience','beginner','intendedUse','personal-learning','sources','[]'::jsonb,'referenceNotes',repeat('x',10001)),'education'),'Separate notes bound enforced');
select ok(private.complete_generation_input('{"mode":"branding","title":"Video","productName":"Backpack","intendedUse":"promotional","sources":[{"assetId":"b1400000-0000-4000-8000-000000000001","role":"image"}]}','branding'),'Branding description stays optional');
select ok(not private.complete_generation_input('{"mode":"branding","title":"Video","productName":"Backpack","intendedUse":"promotional","sources":[{"assetId":"b1400000-0000-4000-8000-000000000001","role":"logo"}]}','branding'),'Logo alone is insufficient');
select ok(not private.complete_generation_input('{"mode":"branding","title":"Video","productName":"Backpack","benefits":[" "],"intendedUse":"promotional","sources":[{"assetId":"b1400000-0000-4000-8000-000000000001","role":"image"}]}','branding'),'Blank benefit rejected for generation');
select ok(not private.complete_generation_input('{"mode":"branding","title":"Video","productName":"Backpack","brandColors":["green"],"intendedUse":"promotional","sources":[{"assetId":"b1400000-0000-4000-8000-000000000001","role":"image"}]}','branding'),'Hex colors validated');
select ok(not private.complete_generation_input('{"mode":"software","title":"Video","softwareName":"App","brief":"Does things","intendedUse":"promotional","sources":[]}','software'),'Software source required');
select ok(not private.complete_generation_input('{"mode":"software","title":"Video","softwareName":"App","brief":"Does things","intendedUse":"promotional","sources":[{"assetId":"b1400000-0000-4000-8000-000000000001","role":"image"},{"assetId":"b1400000-0000-4000-8000-000000000001","role":"image"}]}','software'),'Duplicate source IDs rejected');
select ok(not private.complete_generation_input('{"mode":"branding","title":"Video","productName":"Backpack","intendedUse":"promotional","sources":[{"assetId":"b1400000000040008000000000000001","role":"image"}]}','branding'),'Noncontract UUID spelling rejected before cast');
select ok(not private.complete_generation_input('{"mode":"branding","title":"Video","productName":"Backpack","intendedUse":"promotional","sources":[{"assetId":" b1400000-0000-4000-8000-000000000001 ","role":"image"}]}','branding'),'Noncontract UUID spelling rejected before cast');
select ok(not private.complete_generation_input('{"mode":"branding","title":"Video","productName":"Backpack","intendedUse":"promotional","sources":[{"assetId":"b1400000-0000-0000-0000-000000000001","role":"image"}]}','branding'),'Noncontract UUID spelling rejected before cast');
select * from finish();
rollback;
